"""Coverage report (tools/REPORT.md) for each build."""
from collections import Counter

from .foreverdb import MIN_OBSERVED_DROPS
from .merge import PROFESSIONS


def _pct(a, b):
    return "%d / %d (%d%%)" % (a, b, round(100.0 * a / b)) if b else "0 / 0"


def build_report(catalog, meta, fdb, list_limit=60):
    rs = catalog["recipes"]
    npcs = catalog["npcs"]
    lines = ["# Data build report", "",
             "*Generated by `tools/build_data.py`. Do not edit.*", "",
             "## Sources", "",
             "| Source | Pin |", "|---|---|"]
    for name, pin in meta["sources"].items():
        lines.append("| %s | %s |" % (name, pin))
    lines += ["", "## Totals", "",
              "| Profession | Recipes | New in Forever | Unknown source | Unverified claim |",
              "|---|---|---|---|---|"]
    by_line = Counter(r["skillLine"] for r in rs)
    for line in sorted(by_line, key=lambda k: PROFESSIONS[k][1]):
        sub = [r for r in rs if r["skillLine"] == line]
        lines.append("| %s | %d | %d | %d | %d |" % (
            PROFESSIONS[line][1], len(sub), sum(r["new"] for r in sub),
            sum(r["unknown"] for r in sub), sum(bool(r["unverified"]) for r in sub)))
    lines.append("| **All** | **%d** | **%d** | **%d** | **%d** |" % (
        len(rs), sum(r["new"] for r in rs), sum(r["unknown"] for r in rs), sum(bool(r["unverified"]) for r in rs)))
    lines.append("")
    lines.append("Profession rank spells (not recipes): %d." % len(catalog["ranks"]))

    def has_pos(n):
        p = npcs.get(n, {}).get("pos")
        return bool(p and "map" in p)

    def located(n):  # map coordinates, or at least the instance (dungeon bosses)
        return bool(npcs.get(n, {}).get("pos"))

    lines += ["", "## Coverage", "", "| Check | New | Classic |", "|---|---|---|"]
    for label, pred, base in (
        ("Skill thresholds (yellow/grey)", lambda r: r["yellow"] is not None, lambda r: True),
        ("Category ID", lambda r: r["category"] is not None, lambda r: True),
        ("Recipe item known (`teach`)", lambda r: bool(r["teach"]), lambda r: "auto" not in r["sources"] and "trainer" not in r["sources"]),
        ("Vendor recipes: all vendors placed on a map", lambda r: all(has_pos(n) for n in r["vendors"]), lambda r: bool(r["vendors"])),
        ("Drop recipes: a drop NPC on a map or in a known instance", lambda r: any(located(n) for n, _ in r["drops"]), lambda r: bool(r["drops"])),
        ("Drop recipes: a drop rate is known", lambda r: any(c is not None for _, c in r["drops"]), lambda r: bool(r["drops"])),
        ("Quest recipes: quest giver known", lambda r: all(catalog["quests"].get(q, {}).get("giverNpcs") or catalog["quests"].get(q, {}).get("giverObjects") for q in r["quests"]), lambda r: bool(r["quests"])),
    ):
        cells = []
        for new in (True, False):
            sub = [r for r in rs if r["new"] == new and base(r)]
            cells.append(_pct(sum(1 for r in sub if pred(r)), len(sub)))
        lines.append("| %s | %s | %s |" % (label, cells[0], cells[1]))
    lines.append("")
    lines.append("Categories: %s." % ("%d categories with names (TradeSkillCategory)" % len(catalog["categories"])
                                     if catalog["categoriesAvailable"] else
                                     "IDs only. TradeSkillCategory wasn't available, so names come from the game at runtime"))
    lines.append("NPCs: %d (%d on a map, %d more with only an instance). Objects: %d. Quests: %d." % (
        len(npcs), sum(1 for n in npcs if has_pos(n)), sum(1 for n in npcs if located(n) and not has_pos(n)),
        len(catalog["objects"]), len(catalog["quests"])))
    lines.append("Drop rates set aside for a small sample (fewer than %d drops seen): %d." % (
        MIN_OBSERVED_DROPS, len(fdb.small_samples)))

    def recipe_label(r):
        item = r["teach"][0] if r["teach"] else r["creates"]
        name = fdb.item_name(item) if item else None
        return "%s `%d` %s" % (PROFESSIONS[r["skillLine"]][1], r["spell"], name or "?")

    gaps = [r for r in rs if r["unverified"]]
    lines += ["", "## Claimed by WhatsTraining but no NPC / quest found (%d)" % len(gaps), "",
              "Fill these in `tools/overrides.json`, or harvest them in game.", ""]
    for r in sorted(gaps, key=lambda r: (not r["new"], r["skillLine"], r["spell"]))[:list_limit]:
        lines.append("- %s: %s" % (recipe_label(r), ", ".join(r["unverified"])))
    if len(gaps) > list_limit:
        lines.append("- ... and %d more" % (len(gaps) - list_limit))

    unknown = [r for r in rs if r["unknown"]]
    lines += ["", "## No known source (%d)" % len(unknown), ""]
    for r in sorted(unknown, key=lambda r: (not r["new"], r["skillLine"], r["spell"]))[:list_limit]:
        lines.append("- " + recipe_label(r))
    if len(unknown) > list_limit:
        lines.append("- ... and %d more" % (len(unknown) - list_limit))

    # The learn level comes from WhatsTraining (Classic values), the thresholds from Forever's client.
    above = [r for r in rs if r["learn"] and r["yellow"] and r["learn"] > r["yellow"]]
    lines += ["", "## Learn level above the yellow threshold (%d)" % len(above), "",
              "The learn level is probably stale. Check \"Requires <Profession> (N)\" on the recipe item's tooltip "
              "in game and fix confirmed values in `tools/overrides.json`.", ""]
    for r in sorted(above, key=lambda r: (not r["new"], r["skillLine"], r["spell"]))[:list_limit]:
        lines.append("- %s: learn %d, yellow %d" % (recipe_label(r), r["learn"], r["yellow"]))
    if len(above) > list_limit:
        lines.append("- ... and %d more" % (len(above) - list_limit))

    unlisted = catalog["unlisted"]
    lines += ["", "## In the client's SkillLineAbility with a recipe category, but not in WhatsTraining (%d)" % len(unlisted), "",
              "Usually ranks, removed or test spells. Review before adding any to overrides.", ""]
    per = Counter(line for line, _, _ in unlisted)
    lines.append(", ".join("%s %d" % (PROFESSIONS[k][1], v) for k, v in sorted(per.items(), key=lambda kv: PROFESSIONS[kv[0]][1])) or "None.")

    if catalog["overridesApplied"]:
        lines += ["", "## Overrides applied", ""]
        for spell, what in catalog["overridesApplied"]:
            lines.append("- `%d`: %s" % (spell, what))
    return "\n".join(lines) + "\n"
